#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

struct step {
	ll val; int cost;
	bool operator<(const step &other) const {
		return other.cost < cost;
	}
};

set<ll> visitedNodes;

bool visitedAlready(ll c) {
	return visitedNodes.count(c) > 0;
}

step computeUupper(ll n){
	ll res = 0;
	int digitsCount = 0;
	while(res < n){
		res = res * 10 + 1;
		digitsCount++;
	}
	return {res, digitsCount};
}

step computeUpperLimit(ll n){
	ll res = 0;
	int digitsCount = 0;
	while(res * 10 + 1 <= n){
		res = res * 10 + 1;
		digitsCount++;
	}
	ll baseRes = res;
	int baseDigits = digitsCount;
	while(res < n){
		res += baseRes;
		digitsCount += baseDigits;
	}
	return {res, digitsCount};
}

step computeLowerLimit(ll n){
	ll res = 0;
	int digitsCount = 0;
	while(res * 10 + 1 <= n){
		res = res * 10 + 1;
		digitsCount++;
	}
	ll baseRes = res;
	int baseDigits = digitsCount;
	while(res + baseRes <= n){
		res += baseRes;
		digitsCount += baseDigits;
	}
	return {res, digitsCount};
}

int main() {
	ll n;
	cin >> n;

	priority_queue<step> pq;

	pq.push({n, 0});

	while(pq.top().val != 0){
		ll currentVal = pq.top().val;
		int currentCost = pq.top().cost;
		pq.pop();

		if(visitedAlready(currentVal))
			continue;
		visitedNodes.insert(currentVal);

		for (auto s : { computeLowerLimit(currentVal), computeUpperLimit(currentVal), computeUupper(currentVal) }) {
			s.cost += currentCost;
			s.val = abs(currentVal - s.val);
			pq.push(s);
		}
	}

	cout << pq.top().cost << endl;
}
